#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    rolls: Vec<u16>,
    frame: u8,          // current frame (0..=9); 10 once the game is over
    pins_in_frame: u16, // pins knocked down in the current frame (frames 1..=9)
    tenth_rolls: u8,    // number of rolls made in the 10th frame
}

