        Self {
            rolls: Vec::new(),
            frame: 0,
            pins_in_frame: 0,
            tenth_rolls: 0,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if self.frame == 10 {
            return Err(Error::GameComplete);
        }

        if self.frame < 9 {
            let available = 10 - self.pins_in_frame;
            if pins > available {
                return Err(Error::NotEnoughPinsLeft);
            }
            self.pins_in_frame += pins;
            if self.pins_in_frame == 10 {
                self.frame += 1;
                self.pins_in_frame = 0;
            }
        } else {
            let available = self.tenth_frame_available();
            if pins > available {
                return Err(Error::NotEnoughPinsLeft);
            }
            self.tenth_rolls += 1;
            if self.tenth_rolls == 2 {
                let total = self.tenth_frame_total();
                if total < 10 {
                    self.frame = 10;
                }
            } else if self.tenth_rolls == 3 {
                self.frame = 10;
            }
        }

        self.rolls.push(pins);
        Ok(())
    }

    /// Pins still standing against the next ball in the 10th frame.
    fn tenth_frame_available(&self) -> u16 {
        match self.tenth_rolls {
            0 => 10,
            1 => {
                let first = self.rolls[self.rolls.len() - 1];
                if first == 10 { 10 } else { 10 - first }
            }
            _ => {
                let second = self.rolls[self.rolls.len() - 1];
                if second == 10 { 10 } else { 10 - second }
            }
        }
    }

    fn tenth_frame_total(&self) -> u16 {
        self.rolls
            .iter()
            .skip(self.rolls.len() - self.tenth_rolls as usize)
            .sum()
    }

    pub fn score(&self) -> Option<u16> {
        if self.frame != 10 {
            return None;
        }

        let mut total = 0u16;
        let mut i = 0;
        for _ in 0..10 {
            if self.rolls[i] == 10 {
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2];
                i += 1;
            } else if self.rolls[i] + self.rolls[i + 1] == 10 {
                total += 10 + self.rolls[i + 2];
                i += 2;
            } else {
                total += self.rolls[i] + self.rolls[i + 1];
                i += 2;
            }
        }
        Some(total)
    }
}
